SELECT *, case when now() > start_date and end_date > now() then 'Y' else 'N' end as showing_yn FROM popup WHERE 1=1 and del_yn = 'N'
and (title like CONCAT('%', #{keyword}, '%') or content like CONCAT('%', #{keyword}, '%'))
and title like CONCAT('%', #{keyword}, '%')
and content like CONCAT('%', #{keyword}, '%')
and start_date <= now() and end_date >= now()
and show_pc = #{show_pc}
and show_mo = #{show_mo}
and lang = #{lang}
order by reg_date desc LIMIT #{pagination.limitStart}, #{recordSize}

SELECT count(*) FROM popup WHERE 1=1 and del_yn = 'N'
and (title like CONCAT('%', #{keyword}, '%') or content like CONCAT('%', #{keyword}, '%'))
and title like CONCAT('%', #{keyword}, '%')
and content like CONCAT('%', #{keyword}, '%')
and start_date <= now() and end_date >= now()
and show_pc = #{show_pc}
and show_mo = #{show_mo}
and lang = #{lang}

